		public void TestProcessNexdocLodgeUniversalEvent()
		{
			var exdocHeader = declaration.QuarantineInvoice.QuarantineExDocHeader;
			exdocHeader.QH_RequestForPermitNumber = "REX0000013011";

			AssertEquals("Should be an RFP entry", CusEntryNumber.EntryType.RequestForPermitStatus, exdocHeader.RequestForPermitEntryType);
			AssertEquals("B00001139", declaration.JE_DeclarationReference);
			AssertEquals("JE_MessageStatus should be empty", "", declaration.JE_MessageStatus);
			setupFactory.Save();

			var incomingEvent = @"
<UniversalEvent>
	<Event>
		<DataContext>
			<DataProvider>NEXDOCS</DataProvider>
			<DataTargetCollection>
				<DataTarget>
					<Key>B00001139</Key>
					<Type>CustomsDeclaration</Type>
				</DataTarget>
			</DataTargetCollection>
		</DataContext>
		<EventTime>2015-10-19T20:17:41</EventTime>
		<EventType>MRR</EventType>
		<EventReference>MST=LODGE</EventReference>
		<ContextCollection>
			<Context>
				<Type>RexNumber</Type>
				<Value>REX0000013011</Value>
			</Context>
			<Context>
				<Type>ComplianceStatus</Type>
				<Value>HCRD</Value>
			</Context>
			<Context>
				<Type>ECNNumber</Type>
				<Value>ABC123</Value>
			</Context>
		</ContextCollection>
	</Event>
</UniversalEvent>
";

			var serviceTaskLog = new ServiceTaskLogForTesting();
			var message = ProcessUniversalEventMessage(incomingEvent, serviceTaskLog);

			AssertEquals("Message EM_Status", EDIMessageStatusList.Codes.ProcessedOK, message.EM_Status);
			AssertEquals("message.EM_MessageType", EDIMessageTypeList.Codes.XDC, message.EM_MessageType);

			AssertEquals("Service Task Log", "Linked Event to Declaration B00001139.", serviceTaskLog.ToString());
			AssertEquals("Message Log Note", "Linked Event to Declaration B00001139.", message.GetLogNoteText());

			var reloadedDeclaration = new BusinessObjectFactory().Load<JobDeclaration>(declaration.PK);
			var reloadedExDocHeader = reloadedDeclaration.QuarantineInvoice.QuarantineExDocHeader;

			AssertEquals("JE_MessageStatus should be updated", "ACK", reloadedDeclaration.JE_MessageStatus);
			AssertEquals("RFPNumber should be unchanged", "REX0000013011", reloadedExDocHeader.QH_RequestForPermitNumber);
			AssertEquals("RFPNumber EntryStatus should be updated", "HCR", reloadedExDocHeader.RequestForPermitStatus);
		}

