		public void TestProcessNexdocForwardNotifyUniversalEvent()
		{
			var incomingEvent = @"
<UniversalEvent xmlns=""http://www.cargowise.com/Schemas/Universal/2011/11"">
	<Event>
		<DataContext>
			<DataProvider>NEXDOCS</DataProvider>
			<DataTargetCollection>
				<DataTarget>
					<Key></Key>
					<Type>CustomsDeclaration</Type>
				</DataTarget>
			</DataTargetCollection>
		</DataContext>
		<EventTime>2019-06-03T07:09:30</EventTime>
		<EventType>MRR</EventType>
		<EventReference>MST=NOTIF</EventReference>
		<ContextCollection>
			<Context>
				<Type>NotificationDate</Type>
				<Value>2019-06-03T17:08:43.242+10:00</Value>
			</Context>
			<Context>
				<Type>NotificationType</Type>
				<Value>FA</Value>
			</Context>
			<Context>
				<Type>NotificationTitle</Type>
				<Value>Forward Notification requires approval: REX0000028829 (Exporter Reference: BKG190607REF2)</Value>
			</Context>
			<Context>
				<Type>NotificationText</Type>
				<Value>You have received a forward request that requires acceptance.  The forward was sent by CGAA00312.</Value>
			</Context>
		</ContextCollection>
	</Event>
</UniversalEvent>
";

			var message = ProcessUniversalEventMessage(incomingEvent);

			AssertEquals("Message EM_Status", EDIMessageStatusList.Codes.ProcessedOK, message.EM_Status);

			var notificationQuery = new ZQuery();
			notificationQuery.AddToFilter(QuarantineNexDocNotificationSchema.QN_RexNumber, "REX0000028829");
			notificationQuery.AddToFilter(QuarantineNexDocNotificationSchema.QN_ExporterReference, "BKG190607REF2");
			var notification = new BusinessObjectFactory().LoadTop1<QuarantineNexDocNotification>(notificationQuery);

			AssertEquals("QN_NotificationType", "FA", notification.QN_NotificationType);
			AssertEquals("QN_AcknowledgeStatus", "NOT", notification.QN_AcknowledgeStatus);

			var emailSent = Env.OutgoingMailManager.EmailsCreated.FirstOrDefault();
			AssertNotNull("Should have sent an email.", emailSent);
			AssertEquals("Email title", "NEXDOCS Notification FA", emailSent.Subject);
		}

