		public void TestProcessNexdocTransferErrorUniversalEvent()
		{
			var exdocHeader = declaration.QuarantineInvoice.QuarantineExDocHeader;
			exdocHeader.QH_RequestForPermitNumber = "REX0000013011";

			AssertEquals("Should be an RFP entry", CusEntryNumber.EntryType.RequestForPermitStatus, exdocHeader.RequestForPermitEntryType);
			AssertEquals("JE_MessageStatus should be empty", "", declaration.JE_MessageStatus);
			setupFactory.Save();

			var incomingEvent = @"
<UniversalEvent xmlns=""http://www.cargowise.com/Schemas/Universal/2011/11"">
	<Event>
		<DataContext>
			<DataProvider>NEXDOCS</DataProvider>
			<DataTargetCollection>
				<DataTarget>
					<Key></Key>
					<Type>CustomsDeclaration</Type>
				</DataTarget>
			</DataTargetCollection>
		</DataContext>
		<EventTime>2019-06-03T07:09:30</EventTime>
		<EventType>MRR</EventType>
		<ContextCollection>
			<Context>
				<Type>RexNumber</Type>
				<Value>REX0000013011</Value>
			</Context>
			<Context>
				<Type>MessageStatus</Type>
				<Value>ERO</Value>
			</Context>
			<Context>
				<Type>Message</Type>
				<Value>Calling RexOwnership service failed</Value>
			</Context>
			<Context>
				<Type>Message</Type>
				<Value>Transfer is not permitted at ORDER</Value>
			</Context>
		</ContextCollection>
	</Event>
</UniversalEvent>
";

			var message = ProcessUniversalEventMessage(incomingEvent);
			AssertEquals("Message EM_Status", EDIMessageStatusList.Codes.ProcessedOK, message.EM_Status);
			setupFactory.Save();

			var reloadedDeclaration = new BusinessObjectFactory().Load<JobDeclaration>(declaration.PK);
			AssertEquals("JE_MessageStatus should be updated", EDIMessage.Status.Rejected, reloadedDeclaration.JE_MessageStatus);
			var quarantineHeader = reloadedDeclaration.QuarantineInvoice.QuarantineExDocHeader;
			AssertNotNull("Message is loaded into Quarantine Header Messages", quarantineHeader.Messages.FindByPK(message.PK));
		}

