		IEDIMessage ProcessUniversalEventMessage(string messageText, ISimpleLogger logger = null)
		{
			var message = GetQueuedUniversalEventMessage(Factory, messageText);
			var interchange = Factory.New<EDIInterchange>();
			message.EM_EI = interchange.PK;
			interchange.EI_From = "NEXDOCS";
			interchange.EI_InterchangeNum = (interchangeNum++).ToString();
			Factory.SaveForTesting();

			var messageFactory = new BusinessObjectFactory();
			var messageToProcess = messageFactory.Load<IEDIMessage>(message.PK);
			var manager = new UniversalMessageProcessingManager(logger ?? new ServiceTaskLogForTesting());
			using (messageFactory.AddDisposableService())
			{
				manager.Process(messageToProcess);
				messageFactory.Save();

				var allEdocs = messageFactory.Load<JobDeclaration>(declaration.PK)?.DocManagerInfo.AllEDocs.Cast<IDisposable>();
				if (allEdocs != null)
				{
					foreach (var eDoc in allEdocs)
					{
						eDoc.Dispose();
					}
				}
			}

			return messageToProcess;
		}

		void AssertNexdocEDN(string incomingEvent)
		{
			var serviceTaskLog = new ServiceTaskLogForTesting();
			var message = ProcessUniversalEventMessage(incomingEvent, serviceTaskLog);

			AssertEquals("JE_MessageStatus should be updated", "ACK", declaration.JE_MessageStatus);
			AssertEquals("Message EM_Status", EDIMessageStatusList.Codes.ProcessedOK, message.EM_Status);
			AssertEquals("message.EM_MessageType", EDIMessageTypeList.Codes.XDC, message.EM_MessageType);

			AssertEquals("Service Task Log", "Linked Event to Declaration B00001139.", serviceTaskLog.ToString());
			AssertEquals("Message Log Note", "Linked Event to Declaration B00001139.", message.GetLogNoteText());

			var reloadedDeclaration = new BusinessObjectFactory().Load<JobDeclaration>(declaration.PK);
			AssertEquals("DeclarationNumber should be updated", "AAAAAAAYD", reloadedDeclaration.DeclarationNumber);

			var reloadedMessage = reloadedDeclaration.QuarantineInvoice.QuarantineExDocHeader.Messages.FirstOrDefault(m => m.PK == message.PK);
			AssertNotNull("Message should appear in Quarantine Messages collection", reloadedMessage);
		}

