		sealed class DisposableEDocs : System.Collections.Generic.List<IeDoc>, IDisposable
		{
			public DisposableEDocs(System.Collections.Generic.IEnumerable<IeDoc> eDocs) : base(eDocs)
			{
			}

			bool disposed;

			public void Dispose()
			{
				if (!disposed)
				{
					foreach (var eDoc in this.Cast<IDisposable>())
					{
						eDoc.Dispose();
					}

					disposed = true;
				}
			}
		}
	}
